import pandas as pd
import numpy as np
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
import matplotlib.ticker as mticker
import io, base64, textwrap
from datetime import datetime

# ── Load & parse ──────────────────────────────────────────────────────
df = pd.read_csv('/app/benchmark/data.csv')
df['recorded_at'] = pd.to_datetime(df['recorded_at'], utc=True)
df['source_updated_at'] = pd.to_datetime(df['source_updated_at'], utc=True)
df['update_lag_hours'] = (df['recorded_at'] - df['source_updated_at']).dt.total_seconds() / 3600

# ── Section 1: Dataset Overview ───────────────────────────────────────
total_records = len(df)
unique_stations = df['node_id'].nunique()
fuel_types = sorted(df['fuel_type'].unique())
fuel_type_counts = df['fuel_type'].value_counts().sort_index()
date_min = df['recorded_at'].min().strftime('%d %B %Y')
date_max = df['recorded_at'].max().strftime('%d %B %Y')
null_counts = df.isnull().sum()

# ── Section 2: Price Distribution by Fuel Type ────────────────────────
price_stats = df.groupby('fuel_type')['price_pence'].agg(
    ['count', 'mean', 'median', 'std', 'min', 'max',
     lambda x: x.quantile(0.25),
     lambda x: x.quantile(0.75)]
)
price_stats.columns = ['Count', 'Mean', 'Median', 'Std Dev', 'Min', 'Max', 'Q1', 'Q3']
price_stats['IQR'] = price_stats['Q3'] - price_stats['Q1']
price_stats = price_stats.sort_values('Median', ascending=True)

# Box plot
fig, ax = plt.subplots(figsize=(10, 5.5))
fuel_order = price_stats.index.tolist()
box_data = [df[df['fuel_type'] == ft]['price_pence'].dropna().values for ft in fuel_order]
bp = ax.boxplot(box_data, vert=True, patch_artist=True, labels=fuel_order,
                widths=0.5, showfliers=True,
                flierprops=dict(marker='.', markersize=3, alpha=0.3, color='#555'))
colours = ['#2c7bb6', '#abd9e9', '#fdae61', '#d7191c', '#756bb1']
for patch, colour in zip(bp['boxes'], colours[:len(fuel_order)]):
    patch.set_facecolor(colour)
    patch.set_alpha(0.75)
for median in bp['medians']:
    median.set(color='#222', linewidth=1.8)
ax.set_ylabel('Price (pence per litre)', fontsize=11)
ax.set_xlabel('Fuel Type', fontsize=11)
ax.set_title('Price Distribution by Fuel Type', fontsize=13, fontweight='bold')
ax.yaxis.set_major_formatter(mticker.FormatStrFormatter('%.0f'))
ax.grid(axis='y', alpha=0.3)
fig.tight_layout()
buf = io.BytesIO(); fig.savefig(buf, format='png', dpi=150); buf.seek(0)
boxplot_b64 = base64.b64encode(buf.read()).decode(); plt.close()

# Histogram per fuel type
fig, axes = plt.subplots(2, 3, figsize=(14, 8))
axes = axes.flatten()
for i, ft in enumerate(fuel_order):
    subset = df[df['fuel_type'] == ft]['price_pence']
    ax = axes[i]
    ax.hist(subset, bins=40, color=colours[i % len(colours)], alpha=0.75, edgecolor='white', linewidth=0.5)
    ax.set_title(ft, fontsize=11, fontweight='bold')
    ax.set_xlabel('Price (ppl)')
    ax.set_ylabel('Frequency')
    ax.axvline(subset.median(), color='#222', linestyle='--', linewidth=1.2, label=f'Median: {subset.median():.1f}')
    ax.legend(fontsize=8)
    ax.grid(axis='y', alpha=0.25)
for j in range(len(fuel_order), len(axes)):
    axes[j].set_visible(False)
fig.suptitle('Price Histograms by Fuel Type', fontsize=13, fontweight='bold', y=1.01)
fig.tight_layout()
buf = io.BytesIO(); fig.savefig(buf, format='png', dpi=150, bbox_inches='tight'); buf.seek(0)
hist_b64 = base64.b64encode(buf.read()).decode(); plt.close()

# ── Section 3: Price Spread & Competitiveness ─────────────────────────
spread_df = price_stats[['Min', 'Max', 'Q1', 'Q3', 'IQR', 'Median']].copy()
spread_df['Range'] = spread_df['Max'] - spread_df['Min']
spread_df['Range_GBP'] = spread_df['Range'] / 100

# IQR bar chart
fig, ax = plt.subplots(figsize=(9, 5))
x = range(len(spread_df))
bars_range = ax.bar(x, spread_df['Range'], width=0.4, label='Full Range (Max−Min)', color='#d7191c', alpha=0.65, align='center')
bars_iqr = ax.bar([i + 0.4 for i in x], spread_df['IQR'], width=0.4, label='IQR (Q3−Q1)', color='#2c7bb6', alpha=0.75, align='center')
ax.set_xticks([i + 0.2 for i in x])
ax.set_xticklabels(spread_df.index, fontsize=10)
ax.set_ylabel('Price Difference (pence)', fontsize=11)
ax.set_title('Price Spread by Fuel Type: Full Range vs IQR', fontsize=13, fontweight='bold')
ax.legend(fontsize=10)
ax.grid(axis='y', alpha=0.3)
for bar in bars_range:
    h = bar.get_height()
    ax.text(bar.get_x() + bar.get_width()/2, h + 0.5, f'{h:.1f}p', ha='center', fontsize=8)
for bar in bars_iqr:
    h = bar.get_height()
    ax.text(bar.get_x() + bar.get_width()/2, h + 0.5, f'{h:.1f}p', ha='center', fontsize=8)
fig.tight_layout()
buf = io.BytesIO(); fig.savefig(buf, format='png', dpi=150); buf.seek(0)
spread_b64 = base64.b64encode(buf.read()).decode(); plt.close()

# ── Section 4: Update Freshness ───────────────────────────────────────
lag = df['update_lag_hours']
lag_positive = lag[lag >= 0]
lag_negative = lag[lag < 0]

lag_stats = {
    'mean': lag.mean(),
    'median': lag.median(),
    'std': lag.std(),
    'min': lag.min(),
    'max': lag.max(),
    'q1': lag.quantile(0.25),
    'q3': lag.quantile(0.75),
    'pct_under_1h': (lag.abs() <= 1).mean() * 100,
    'pct_under_6h': (lag.abs() <= 6).mean() * 100,
    'pct_under_24h': (lag.abs() <= 24).mean() * 100,
    'pct_over_48h': (lag > 48).mean() * 100,
    'pct_over_168h': (lag > 168).mean() * 100,
    'negative_count': len(lag_negative),
    'negative_pct': len(lag_negative) / len(lag) * 100,
}

# Lag histogram (capped at 72h for readability)
fig, ax = plt.subplots(figsize=(10, 5))
lag_capped = lag_positive[lag_positive <= 72]
ax.hist(lag_capped, bins=60, color='#2c7bb6', alpha=0.75, edgecolor='white', linewidth=0.4)
ax.axvline(lag.median(), color='#d7191c', linestyle='--', linewidth=1.5, label=f'Median: {lag.median():.1f}h')
ax.set_xlabel('Update Lag (hours)', fontsize=11)
ax.set_ylabel('Frequency', fontsize=11)
ax.set_title('Distribution of Retailer Update Lag (0–72 hours)', fontsize=13, fontweight='bold')
ax.legend(fontsize=10)
ax.grid(axis='y', alpha=0.3)
fig.tight_layout()
buf = io.BytesIO(); fig.savefig(buf, format='png', dpi=150); buf.seek(0)
lag_hist_b64 = base64.b64encode(buf.read()).decode(); plt.close()

# Lag by fuel type
lag_by_fuel = df.groupby('fuel_type')['update_lag_hours'].agg(['median', 'mean', 'std']).sort_values('median')

fig, ax = plt.subplots(figsize=(9, 5))
x = range(len(lag_by_fuel))
ax.bar(x, lag_by_fuel['median'], color='#2c7bb6', alpha=0.75)
ax.set_xticks(x)
ax.set_xticklabels(lag_by_fuel.index, fontsize=10)
ax.set_ylabel('Median Lag (hours)', fontsize=11)
ax.set_title('Median Update Lag by Fuel Type', fontsize=13, fontweight='bold')
ax.grid(axis='y', alpha=0.3)
for i, v in enumerate(lag_by_fuel['median']):
    ax.text(i, v + 0.2, f'{v:.1f}h', ha='center', fontsize=9)
fig.tight_layout()
buf = io.BytesIO(); fig.savefig(buf, format='png', dpi=150); buf.seek(0)
lag_fuel_b64 = base64.b64encode(buf.read()).decode(); plt.close()

# ── Section 5: Station Coverage & Fuel Type Availability ──────────────
station_fuel_counts = df.groupby('node_id')['fuel_type'].nunique()
station_fuel_dist = station_fuel_counts.value_counts().sort_index()

fuel_station_coverage = df.groupby('fuel_type')['node_id'].nunique().sort_values(ascending=False)

records_per_station = df.groupby('node_id').size()
rps_stats = {
    'mean': records_per_station.mean(),
    'median': records_per_station.median(),
    'min': records_per_station.min(),
    'max': records_per_station.max(),
}

fig, (ax1, ax2) = plt.subplots(1, 2, figsize=(13, 5))
ax1.bar(station_fuel_dist.index.astype(str), station_fuel_dist.values, color='#2c7bb6', alpha=0.75)
ax1.set_xlabel('Number of Fuel Types Reported', fontsize=11)
ax1.set_ylabel('Number of Stations', fontsize=11)
ax1.set_title('Station Distribution by Fuel Type Count', fontsize=12, fontweight='bold')
ax1.grid(axis='y', alpha=0.3)
for i, v in enumerate(station_fuel_dist.values):
    ax1.text(i, v + 5, str(v), ha='center', fontsize=9)

ax2.barh(fuel_station_coverage.index, fuel_station_coverage.values, color='#fdae61', alpha=0.8)
ax2.set_xlabel('Number of Unique Stations', fontsize=11)
ax2.set_title('Station Coverage by Fuel Type', fontsize=12, fontweight='bold')
ax2.grid(axis='x', alpha=0.3)
for i, v in enumerate(fuel_station_coverage.values):
    ax2.text(v + 5, i, str(v), va='center', fontsize=9)
fig.tight_layout()
buf = io.BytesIO(); fig.savefig(buf, format='png', dpi=150); buf.seek(0)
coverage_b64 = base64.b64encode(buf.read()).decode(); plt.close()


# ── Build price stats table rows ──────────────────────────────────────
def stats_table_rows():
    rows = []
    for ft in price_stats.index:
        r = price_stats.loc[ft]
        rows.append(f"""<tr>
            <td><strong>{ft}</strong></td>
            <td>{int(r['Count']):,}</td>
            <td>{r['Mean']:.1f}</td>
            <td>{r['Median']:.1f}</td>
            <td>{r['Std Dev']:.1f}</td>
            <td>{r['Min']:.1f}</td>
            <td>{r['Q1']:.1f}</td>
            <td>{r['Q3']:.1f}</td>
            <td>{r['Max']:.1f}</td>
            <td>{r['IQR']:.1f}</td>
        </tr>""")
    return '\n'.join(rows)

def spread_table_rows():
    rows = []
    for ft in spread_df.index:
        r = spread_df.loc[ft]
        rows.append(f"""<tr>
            <td><strong>{ft}</strong></td>
            <td>{r['Min']:.1f}</td>
            <td>{r['Q1']:.1f}</td>
            <td>{r['Median']:.1f}</td>
            <td>{r['Q3']:.1f}</td>
            <td>{r['Max']:.1f}</td>
            <td>{r['IQR']:.1f}</td>
            <td><strong>{r['Range']:.1f}</strong></td>
            <td>£{r['Range_GBP']:.2f}</td>
        </tr>""")
    return '\n'.join(rows)

def lag_fuel_table_rows():
    rows = []
    for ft in lag_by_fuel.index:
        r = lag_by_fuel.loc[ft]
        rows.append(f"""<tr>
            <td><strong>{ft}</strong></td>
            <td>{r['median']:.1f}</td>
            <td>{r['mean']:.1f}</td>
            <td>{r['std']:.1f}</td>
        </tr>""")
    return '\n'.join(rows)

def fuel_count_table():
    rows = []
    for ft in fuel_type_counts.sort_index().index:
        c = fuel_type_counts[ft]
        rows.append(f"<tr><td>{ft}</td><td>{c:,}</td><td>{c/total_records*100:.1f}%</td></tr>")
    return '\n'.join(rows)

def null_info():
    if null_counts.sum() == 0:
        return "<p>No null values detected in any column — the dataset is complete.</p>"
    parts = []
    for col, cnt in null_counts.items():
        if cnt > 0:
            parts.append(f"<li><code>{col}</code>: {cnt:,} nulls ({cnt/total_records*100:.2f}%)</li>")
    return "<ul>" + ''.join(parts) + "</ul>"

def coverage_table_rows():
    rows = []
    for ft in fuel_station_coverage.index:
        v = fuel_station_coverage[ft]
        rows.append(f"<tr><td><strong>{ft}</strong></td><td>{v:,}</td><td>{v/unique_stations*100:.1f}%</td></tr>")
    return '\n'.join(rows)

def station_fuel_dist_rows():
    rows = []
    for n_fuels, n_stations in station_fuel_dist.items():
        rows.append(f"<tr><td>{n_fuels}</td><td>{n_stations:,}</td><td>{n_stations/unique_stations*100:.1f}%</td></tr>")
    return '\n'.join(rows)

# ── Stale stations analysis ──
stale_threshold_hours = 168  # 7 days
station_max_lag = df.groupby('node_id')['update_lag_hours'].max()
stale_stations = station_max_lag[station_max_lag > stale_threshold_hours]
n_stale = len(stale_stations)

# ── Key Findings ──
# Compute most/least expensive
most_expensive = price_stats['Median'].idxmax()
least_expensive = price_stats['Median'].idxmin()
most_exp_median = price_stats.loc[most_expensive, 'Median']
least_exp_median = price_stats.loc[least_expensive, 'Median']
widest_range_ft = spread_df['Range'].idxmax()
widest_range_val = spread_df.loc[widest_range_ft, 'Range']
narrowest_iqr_ft = spread_df['IQR'].idxmin()
narrowest_iqr_val = spread_df.loc[narrowest_iqr_ft, 'IQR']

# ── HTML ──────────────────────────────────────────────────────────────
html = f"""<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>UK Retail Fuel Price Trend Analysis — February 2026</title>
<style>
  :root {{
    --primary: #1a365d;
    --accent: #2c7bb6;
    --accent-light: #e8f0fe;
    --text: #1a1a2e;
    --text-secondary: #555;
    --border: #d0d5dd;
    --bg: #f8f9fb;
    --card-bg: #ffffff;
    --red: #d7191c;
    --amber: #fdae61;
  }}
  * {{ margin: 0; padding: 0; box-sizing: border-box; }}
  body {{
    font-family: 'Segoe UI', -apple-system, BlinkMacSystemFont, 'Helvetica Neue', Arial, sans-serif;
    color: var(--text);
    background: var(--bg);
    line-height: 1.65;
    font-size: 15px;
  }}
  .container {{ max-width: 1100px; margin: 0 auto; padding: 0 24px; }}
  header {{
    background: linear-gradient(135deg, var(--primary) 0%, #234e7e 100%);
    color: #fff;
    padding: 48px 0 40px;
  }}
  header h1 {{ font-size: 28px; font-weight: 700; margin-bottom: 8px; }}
  header .subtitle {{ font-size: 15px; opacity: 0.85; line-height: 1.5; max-width: 800px; }}
  header .meta {{ margin-top: 16px; font-size: 13px; opacity: 0.7; }}
  .kpi-row {{
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(190px, 1fr));
    gap: 16px;
    margin: -28px 0 32px;
    position: relative;
    z-index: 1;
  }}
  .kpi-card {{
    background: var(--card-bg);
    border-radius: 10px;
    padding: 20px;
    box-shadow: 0 2px 8px rgba(0,0,0,0.07);
    text-align: center;
  }}
  .kpi-card .value {{ font-size: 26px; font-weight: 700; color: var(--primary); }}
  .kpi-card .label {{ font-size: 12px; color: var(--text-secondary); margin-top: 4px; text-transform: uppercase; letter-spacing: 0.5px; }}
  section {{ margin: 36px 0; }}
  h2 {{
    font-size: 20px;
    font-weight: 700;
    color: var(--primary);
    border-bottom: 3px solid var(--accent);
    padding-bottom: 8px;
    margin-bottom: 20px;
  }}
  h3 {{ font-size: 16px; font-weight: 600; color: var(--primary); margin: 18px 0 10px; }}
  p {{ margin-bottom: 14px; color: var(--text); }}
  table {{
    width: 100%;
    border-collapse: collapse;
    margin: 16px 0 24px;
    font-size: 14px;
    background: var(--card-bg);
    border-radius: 8px;
    overflow: hidden;
    box-shadow: 0 1px 4px rgba(0,0,0,0.05);
  }}
  th {{
    background: var(--primary);
    color: #fff;
    padding: 10px 12px;
    text-align: left;
    font-weight: 600;
    font-size: 13px;
  }}
  td {{ padding: 9px 12px; border-bottom: 1px solid #eee; }}
  tr:last-child td {{ border-bottom: none; }}
  tr:nth-child(even) {{ background: #f9fafb; }}
  .chart-container {{
    background: var(--card-bg);
    border-radius: 10px;
    padding: 16px;
    margin: 20px 0;
    box-shadow: 0 1px 4px rgba(0,0,0,0.05);
    text-align: center;
  }}
  .chart-container img {{ max-width: 100%; height: auto; border-radius: 4px; }}
