def stats_table_rows():
    rows = []
    for ft in price_stats.index:
        r = price_stats.loc[ft]
        rows.append(f"""<tr>
            <td><strong>{ft}</strong></td>
            <td>{int(r['Count']):,}</td>
            <td>{r['Mean']:.1f}</td>
            <td>{r['Median']:.1f}</td>
            <td>{r['Std Dev']:.1f}</td>
            <td>{r['Min']:.1f}</td>
            <td>{r['Q1']:.1f}</td>
            <td>{r['Q3']:.1f}</td>
            <td>{r['Max']:.1f}</td>
            <td>{r['IQR']:.1f}</td>
        </tr>""")
    return '\n'.join(rows)

def spread_table_rows():
    rows = []
    for ft in spread_df.index:
        r = spread_df.loc[ft]
        rows.append(f"""<tr>
            <td><strong>{ft}</strong></td>
            <td>{r['Min']:.1f}</td>
            <td>{r['Q1']:.1f}</td>
            <td>{r['Median']:.1f}</td>
            <td>{r['Q3']:.1f}</td>
            <td>{r['Max']:.1f}</td>
            <td>{r['IQR']:.1f}</td>
            <td><strong>{r['Range']:.1f}</strong></td>
            <td>£{r['Range_GBP']:.2f}</td>
        </tr>""")
    return '\n'.join(rows)

def lag_fuel_table_rows():
    rows = []
    for ft in lag_by_fuel.index:
        r = lag_by_fuel.loc[ft]
        rows.append(f"""<tr>
            <td><strong>{ft}</strong></td>
            <td>{r['median']:.1f}</td>
            <td>{r['mean']:.1f}</td>
            <td>{r['std']:.1f}</td>
        </tr>""")
    return '\n'.join(rows)

def fuel_count_table():
    rows = []
    for ft in fuel_type_counts.sort_index().index:
        c = fuel_type_counts[ft]
        rows.append(f"<tr><td>{ft}</td><td>{c:,}</td><td>{c/total_records*100:.1f}%</td></tr>")
    return '\n'.join(rows)

def null_info():
    if null_counts.sum() == 0:
        return "<p>No null values detected in any column — the dataset is complete.</p>"
    parts = []
    for col, cnt in null_counts.items():
        if cnt > 0:
            parts.append(f"<li><code>{col}</code>: {cnt:,} nulls ({cnt/total_records*100:.2f}%)</li>")
    return "<ul>" + ''.join(parts) + "</ul>"

def coverage_table_rows():
    rows = []
    for ft in fuel_station_coverage.index:
        v = fuel_station_coverage[ft]
        rows.append(f"<tr><td><strong>{ft}</strong></td><td>{v:,}</td><td>{v/unique_stations*100:.1f}%</td></tr>")
    return '\n'.join(rows)

def station_fuel_dist_rows():
    rows = []
    for n_fuels, n_stations in station_fuel_dist.items():
        rows.append(f"<tr><td>{n_fuels}</td><td>{n_stations:,}</td><td>{n_stations/unique_stations*100:.1f}%</td></tr>")
    return '\n'.join(rows)

