import pandas as pd
import numpy as np
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
import matplotlib.ticker as mticker
import io, base64, textwrap
from datetime import datetime

# ── Load & parse ──────────────────────────────────────────────────────
df = pd.read_csv('/app/benchmark/data.csv')
df['recorded_at'] = pd.to_datetime(df['recorded_at'], utc=True)
df['source_updated_at'] = pd.to_datetime(df['source_updated_at'], utc=True)
df['update_lag_hours'] = (df['recorded_at'] - df['source_updated_at']).dt.total_seconds() / 3600

# ── Section 1: Dataset Overview ───────────────────────────────────────
total_records = len(df)
unique_stations = df['node_id'].nunique()
fuel_types = sorted(df['fuel_type'].unique())
fuel_type_counts = df['fuel_type'].value_counts().sort_index()
date_min = df['recorded_at'].min().strftime('%d %B %Y')
date_max = df['recorded_at'].max().strftime('%d %B %Y')
null_counts = df.isnull().sum()

# ── Section 2: Price Distribution by Fuel Type ────────────────────────
price_stats = df.groupby('fuel_type')['price_pence'].agg(
    ['count', 'mean', 'median', 'std', 'min', 'max',
     lambda x: x.quantile(0.25),
     lambda x: x.quantile(0.75)]
)
price_stats.columns = ['Count', 'Mean', 'Median', 'Std Dev', 'Min', 'Max', 'Q1', 'Q3']
price_stats['IQR'] = price_stats['Q3'] - price_stats['Q1']
price_stats = price_stats.sort_values('Median', ascending=True)

# Box plot
fig, ax = plt.subplots(figsize=(10, 5.5))
fuel_order = price_stats.index.tolist()
box_data = [df[df['fuel_type'] == ft]['price_pence'].dropna().values for ft in fuel_order]
bp = ax.boxplot(box_data, vert=True, patch_artist=True, labels=fuel_order,
                widths=0.5, showfliers=True,
                flierprops=dict(marker='.', markersize=3, alpha=0.3, color='#555'))
colours = ['#2c7bb6', '#abd9e9', '#fdae61', '#d7191c', '#756bb1']
for patch, colour in zip(bp['boxes'], colours[:len(fuel_order)]):
    patch.set_facecolor(colour)
    patch.set_alpha(0.75)
for median in bp['medians']:
    median.set(color='#222', linewidth=1.8)
ax.set_ylabel('Price (pence per litre)', fontsize=11)
ax.set_xlabel('Fuel Type', fontsize=11)
ax.set_title('Price Distribution by Fuel Type', fontsize=13, fontweight='bold')
ax.yaxis.set_major_formatter(mticker.FormatStrFormatter('%.0f'))
ax.grid(axis='y', alpha=0.3)
fig.tight_layout()
buf = io.BytesIO(); fig.savefig(buf, format='png', dpi=150); buf.seek(0)
boxplot_b64 = base64.b64encode(buf.read()).decode(); plt.close()

# Histogram per fuel type
fig, axes = plt.subplots(2, 3, figsize=(14, 8))
axes = axes.flatten()
for i, ft in enumerate(fuel_order):
    subset = df[df['fuel_type'] == ft]['price_pence']
    ax = axes[i]
    ax.hist(subset, bins=40, color=colours[i % len(colours)], alpha=0.75, edgecolor='white', linewidth=0.5)
    ax.set_title(ft, fontsize=11, fontweight='bold')
    ax.set_xlabel('Price (ppl)')
    ax.set_ylabel('Frequency')
    ax.axvline(subset.median(), color='#222', linestyle='--', linewidth=1.2, label=f'Median: {subset.median():.1f}')
    ax.legend(fontsize=8)
    ax.grid(axis='y', alpha=0.25)
for j in range(len(fuel_order), len(axes)):
    axes[j].set_visible(False)
fig.suptitle('Price Histograms by Fuel Type', fontsize=13, fontweight='bold', y=1.01)
fig.tight_layout()
buf = io.BytesIO(); fig.savefig(buf, format='png', dpi=150, bbox_inches='tight'); buf.seek(0)
hist_b64 = base64.b64encode(buf.read()).decode(); plt.close()

# ── Section 3: Price Spread & Competitiveness ─────────────────────────
spread_df = price_stats[['Min', 'Max', 'Q1', 'Q3', 'IQR', 'Median']].copy()
spread_df['Range'] = spread_df['Max'] - spread_df['Min']
spread_df['Range_GBP'] = spread_df['Range'] / 100

# IQR bar chart
fig, ax = plt.subplots(figsize=(9, 5))
x = range(len(spread_df))
bars_range = ax.bar(x, spread_df['Range'], width=0.4, label='Full Range (Max−Min)', color='#d7191c', alpha=0.65, align='center')
bars_iqr = ax.bar([i + 0.4 for i in x], spread_df['IQR'], width=0.4, label='IQR (Q3−Q1)', color='#2c7bb6', alpha=0.75, align='center')
ax.set_xticks([i + 0.2 for i in x])
ax.set_xticklabels(spread_df.index, fontsize=10)
ax.set_ylabel('Price Difference (pence)', fontsize=11)
ax.set_title('Price Spread by Fuel Type: Full Range vs IQR', fontsize=13, fontweight='bold')
ax.legend(fontsize=10)
ax.grid(axis='y', alpha=0.3)
for bar in bars_range:
    h = bar.get_height()
    ax.text(bar.get_x() + bar.get_width()/2, h + 0.5, f'{h:.1f}p', ha='center', fontsize=8)
for bar in bars_iqr:
    h = bar.get_height()
    ax.text(bar.get_x() + bar.get_width()/2, h + 0.5, f'{h:.1f}p', ha='center', fontsize=8)
fig.tight_layout()
buf = io.BytesIO(); fig.savefig(buf, format='png', dpi=150); buf.seek(0)
spread_b64 = base64.b64encode(buf.read()).decode(); plt.close()

# ── Section 4: Update Freshness ───────────────────────────────────────
lag = df['update_lag_hours']
lag_positive = lag[lag >= 0]
lag_negative = lag[lag < 0]

lag_stats = {
    'mean': lag.mean(),
    'median': lag.median(),
    'std': lag.std(),
    'min': lag.min(),
    'max': lag.max(),
    'q1': lag.quantile(0.25),
    'q3': lag.quantile(0.75),
    'pct_under_1h': (lag.abs() <= 1).mean() * 100,
    'pct_under_6h': (lag.abs() <= 6).mean() * 100,
    'pct_under_24h': (lag.abs() <= 24).mean() * 100,
